<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {api,state} from '../state';import {createLibraryApi,contributionLibraries,defaultLibraryID,type ContentKind,type LibraryRef} from '../api/libraries';import {errorMessage} from '../api/errors';
const props=defineProps<{modelValue:number;kind:ContentKind;disabled?:boolean}>(),emit=defineEmits<{'update:modelValue':[number]}>(),client=createLibraryApi(api);
const libraries=ref<LibraryRef[]>([]),loading=ref(false),error=ref('');let epoch=0,closed=false;
const targets=computed(()=>contributionLibraries(libraries.value,props.kind)),archivedDefault=computed(()=>libraries.value.find(lib=>lib.content_kind===props.kind&&lib.owner_user_id===state.user?.id&&lib.is_personal_default&&lib.archived&&lib.can_manage));
async function load(){const g=++epoch;loading.value=true;error.value='';try{const response=await client.libraries(false,true);if(closed||g!==epoch)return;libraries.value=response.items??[];if(!targets.value.some(lib=>lib.id===props.modelValue))emit('update:modelValue',defaultLibraryID(libraries.value,state.user?.id??0,props.kind))}catch(e){if(g===epoch)error.value=errorMessage(e)}finally{if(g===epoch)loading.value=false}}
async function restore(){if(!archivedDefault.value)return;try{await client.restore(archivedDefault.value.id);await load()}catch(e){error.value=errorMessage(e)}}
function focusLoad(){if(document.visibilityState==='visible'&&!state.offline&&!props.disabled)void load()}
onMounted(()=>{void load();window.addEventListener('focus',focusLoad);window.addEventListener('online',focusLoad)});watch(()=>props.disabled,value=>{if(!value)void load()});watch(()=>props.kind,load);watch(()=>state.accessEpoch,load);onBeforeUnmount(()=>{window.removeEventListener('focus',focusLoad);window.removeEventListener('online',focusLoad);closed=true;epoch++});
</script>
<template><div class="library-target"><label>导入到<select :value="modelValue" :disabled="disabled||loading" @change="emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option value="0">{{loading?'正在读取书库…':'请选择可贡献的书库'}}</option><option v-for="lib in targets" :key="lib.id" :value="lib.id">{{lib.name}}{{lib.is_personal_default&&lib.owner_user_id===state.user?.id?'（我的个人库）':lib.visibility==='shared'?'（共享）':''}}</option></select></label><p v-if="modelValue" class="hint">默认进入自己的个人库。选择已获贡献权限的库，可与授权成员共享。</p><p v-if="error" role="alert" class="error">{{error}} <button type="button" @click="load">重试</button></p><p v-if="archivedDefault&&!modelValue">个人默认库已归档。<button type="button" :disabled="disabled" @click="restore">恢复我的{{kind==='comic'?'漫画':'图书'}}库</button></p></div></template>
<style scoped>.library-target{max-width:650px;min-width:0}.library-target select{width:100%;min-width:0}.hint{color:var(--muted);font-size:13px;margin:6px 0 12px}</style>
